package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }

    /**
     * Helper to access the private field _elementDeserializer via reflection
     * because it is not exposed via public API.
     */
    private void setElementDeserializer(StringArrayDeserializer target, com.fasterxml.jackson.databind.JsonDeserializer<?> deser) throws Exception {
        java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(target, deser);
    }

    private com.fasterxml.jackson.databind.JsonDeserializer<?> getElementDeserializer(StringArrayDeserializer target) throws Exception {
        java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        return (com.fasterxml.jackson.databind.JsonDeserializer<?>) field.get(target);
    }

    @Test
    public void testCreateContextual_ReturnsThis_WhenNoChanges() throws Exception {
        // Setup: _elementDeserializer is already the default/null or same as result
        // To trigger "return this", the logic must result in deser == _elementDeserializer
        // We use a mock that is NOT the default String deserializer to avoid the isDefaultDeserializer check nulling it
        com.fasterxml.jackson.databind.JsonDeserializer<?> mockDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);
        setElementDeserializer(deserializer, mockDeser);

        // Mock findConvertingContentDeserializer to return the same deser (simulating no converter)
        // Note: findConvertingContentDeserializer is protected. In a real test environment, 
        // we rely on the spy or the fact that we are testing the logic flow.
        // Since we cannot easily mock protected methods of the class under test without spying:
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn(mockDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // If deser is not null, it calls handleSecondaryContextualization
        doReturn(mockDeser).when(ctxt).handleSecondaryContextualization(eq(mockDeser), eq(property));

        com.fasterxml.jackson.databind.JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertSame(spyDeserializer, result);
    }

    @Test
    public void testCreateContextual_ReturnsNewInstance_WhenDeserChanges() throws Exception {
        com.fasterxml.jackson.databind.JsonDeserializer<?> initialDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);
        com.fasterxml.jackson.databind.JsonDeserializer<?> newDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);
        setElementDeserializer(deserializer, initialDeser);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn(initialDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // Simulate secondary contextualization returning a DIFFERENT deserializer
        doReturn(newDeser).when(ctxt).handleSecondaryContextualization(eq(initialDeser), eq(property));

        com.fasterxml.jackson.databind.JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotSame(spyDeserializer, result);
        assertTrue(result instanceof StringArrayDeserializer);
    }

    @Test
    public void testCreateContextual_WhenConverterReturnsNull_UsesContextualValueDeserializer() throws Exception {
        com.fasterxml.jackson.databind.JsonDeserializer<?> newDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);
        setElementDeserializer(deserializer, null);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        // 1. findConvertingContentDeserializer returns null
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        // 2. ctxt.findContextualValueDeserializer returns newDeser
        doReturn(newDeser).when(ctxt).findContextualValueDeserializer(eq(stringType), eq(property));

        com.fasterxml.jackson.databind.JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotSame(spyDeserializer, result);
        // Verify it's a new StringArrayDeserializer wrapping the newDeser
        assertEquals(newDeser, getElementDeserializer((StringArrayDeserializer) result));
    }

    @Test
    public void testCreateContextual_WhenDefaultDeserializerFound_ReturnsNull() throws Exception {
        // We need to simulate isDefaultDeserializer returning true.
        // In Jackson, the default String deserializer is usually StdDeserializer/StringDeserializer.
        // We will mock the behavior by ensuring the result of the lookup is treated as "default".

        com.fasterxml.jackson.databind.JsonDeserializer<?> defaultDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);
        setElementDeserializer(deserializer, defaultDeser);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn(defaultDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        doReturn(defaultDeser).when(ctxt).handleSecondaryContextualization(any(), any());

        // Mock isDefaultDeserializer to return true
        // Note: isDefaultDeserializer is protected. This requires a spy.
        doReturn(true).when(spyDeserializer).isDefaultDeserializer(defaultDeser);

        com.fasterxml.jackson.databind.JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNull(result);
    }

    @Test
    public void testCreateContextual_WhenConverterReturnsNull_AndContextualReturnsNull() throws Exception {
        setElementDeserializer(deserializer, null);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        doReturn(null).when(ctxt).findContextualValueDeserializer(any(), any());

        com.fasterxml.jackson.databind.JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNull(result);
    }
}
